import {spawnSync} from "node:child_process";
import {mkdirSync,readFileSync,writeFileSync,openSync,closeSync,existsSync} from "node:fs";
import {createHash} from "node:crypto";
import {Admission} from "/home/akisarou/Projects/nts-lanes/compiler3-memory/tooling/gate/admission.ts";
import {spawnCounted,instructionsWork} from "/home/akisarou/Projects/nts-lanes/compiler3-memory/tooling/gate/cputime.mjs";
import {measuredCompileEnvironment} from "/home/akisarou/Projects/nts-lanes/compiler3-memory/tooling/gate/canonical-environment.ts";
import {compileCommand,counterProblem,COMPILE_WORK_PROFILE,compileWorkSettings} from "/home/akisarou/Projects/nts-lanes/compiler3-memory/tooling/gate/compile-counter.ts";
const root="/home/akisarou/Projects/nts-lanes/compiler3-memory";
const cache="/home/akisarou/.cache/nts-handover/compiler3/stage2-current";
const tip=spawnSync("git",["rev-parse",process.argv[2]],{cwd:root,encoding:"utf8"}).stdout.trim();
const suite=process.argv[3];if(!["controls","modules"].includes(suite))throw Error("controls or modules required");
const composedParent="ed4698fed552c465efeab1a00cee434e1b55bc3f";
const parentInputs=spawnSync("git",["diff","94f67ba65380",composedParent,"--","compiler","runtime","tooling/cli","Cargo.toml","Cargo.lock"],{cwd:root,encoding:"utf8"});if(parentInputs.status!==0||parentInputs.stdout)throw Error("official before pin does not match composed-parent build inputs");
const beforeCommit="94f67ba653801eb25e4a40a7cba15dbce8e5c84f";
const sha=(value:string|Buffer)=>createHash("sha256").update(value).digest("hex");
const artifacts=Object.fromEntries([beforeCommit,tip].map((commit,at)=>{
 const folder="/home/akisarou/.cache/nts-pins/"+commit.slice(0,12),producer=JSON.parse(readFileSync(folder+"/provenance.json","utf8")),binary=folder+"/nts";
 if(producer.sha!==commit||!producer.clean||producer.applied!==null||producer.binary_sha256!==sha(readFileSync(binary)))throw Error("unbound official artifact");
 return[at?"after":"before",{commit,binary,producer}];
}));
const observer=JSON.parse(readFileSync(cache+"/allocator-observer-v6/instrumented-"+tip.slice(0,12)+".json","utf8"));
if(observer.measured_commit!==tip||observer.producer.sha!==tip||!observer.producer.applied||observer.producer.binary_sha256!==sha(readFileSync(observer.binary)))throw Error("unbound explicitly instrumented observer artifact");
const out=cache+`/cost-v6-${suite}-${tip.slice(0,9)}`;mkdirSync(out,{recursive:true});
writeFileSync(out+"/instrument.ts",readFileSync(import.meta.filename));
const environment=measuredCompileEnvironment(process.env),admission=new Admission({report:console.log});
const problem=instructionsWork();if(problem)throw Error(problem);
async function admitted(){while(!admission.open())await new Promise(resolve=>setTimeout(resolve,2000));}
function current(){const r=spawnSync("git",["rev-parse","HEAD"],{cwd:root,encoding:"utf8"});if(r.status!==0||r.stdout.trim()!==tip)throw Error("workspace revision changed during measurements");}
const controls=["calls","stores","recursive","distributed"].flatMap(family=>[16,32,64].map(n=>({id:`${family}-${n}`,family,n,provider:"rc",config:`/home/akisarou/.cache/nts-compiler3-memory/cost-inputs/${family}-${n}/tsconfig.json`})));
const modules=["runtime/web-platform","runtime/node/fs","runtime/node/http","runtime/node/process","runtime/node/zlib"].flatMap(module=>["nogc","rc"].map(provider=>({id:module.replaceAll("/","_")+"-"+provider,module,provider,config:root+"/"+module+"/tsconfig.json"})));
const entries:any[]=suite==="controls"?controls:modules,rows:any[]=[];
const median=(values:number[])=>[...values].sort((a,b)=>a-b)[1];
async function counted(id:string,arm:string,repeat:number,args:string[]){
 const binary=artifacts[arm==="diagnostic"?"after":arm].binary,file=`${out}/${id}-${arm}-${repeat}.json`;
 let row:any;
 if(existsSync(file)){
  const saved=JSON.parse(readFileSync(file,"utf8"));if(saved.measured_commit!==tip||saved.binary_sha256!==sha(readFileSync(binary))||JSON.stringify(saved.command)!==JSON.stringify([binary,...args]))throw Error("stale counter checkpoint");row=saved.row;
 }else{
  await admitted();const fd=openSync(`${out}/${id}-${arm}-${repeat}.stderr`,"w");
