  writeFileSync(file,JSON.stringify({measured_commit:tip,binary_sha256:sha(readFileSync(binary)),command:[binary,...args],row},null,2)+"\n");
 }
 if(row.status!==0||row.signal||row.error||row.counter_error||!Number.isSafeInteger(row.instructions)||row.instructions<=0||counterProblem(row))throw Error("invalid retained counter");
 return {arm,repeat,...row};
}
async function bracket(entry:any,args:string[],kind:"bytes"|"cpu",reference?:string){
 await admitted();const file=`${out}/${entry.id}-${kind}.json`,base=cache+"/allocator-observer-v6";
