 const phase=result.phases[0];if(JSON.stringify(phase.entry_thread)!==JSON.stringify(phase.return_thread))throw Error("phase switched thread");
 if(kind==="bytes"&&(phase.failed||phase.peak_requested_bytes<=0)||kind==="cpu"&&(phase.cpu_ns<=0||result.process_cpu.total_s<=0))throw Error("invalid phase column");
 return {command,raw_file:file,raw_sha256:sha(readFileSync(file)),...result};
}
for(const entry of entries){
 current();const normal=suite==="modules"?compileCommand(entry.provider,entry.config):["hir",entry.config,"--prepared","--rc","--entry","work","--main","--checkers","1","--backend","c"];
