 for(let repeat=0;repeat<3;repeat++)runs.push(await counted(entry.id,"diagnostic",repeat,diagnostic));
 const bytes=await bracket(entry,diagnostic,"bytes");
 const cpu=await bracket(entry,diagnostic,"cpu",bytes.raw_file);
 const text=readFileSync(`${out}/${entry.id}-bytes.stdout`,"utf8");
 const header=text.split("\n").find(line=>line.startsWith("memory-v2\t"));
 const points=text.split("\n").find(line=>line.startsWith("points-to-changes\t"));
 const events=text.split("\n").find(line=>line.startsWith("memory-events\t"));
 if(!header||!points||!events)throw Error("missing report columns");
 const completed=header.endsWith("failure=None");if(suite==="controls"&&!completed)throw Error("control did not finish: "+header);
 const medians=Object.fromEntries(["before","after","diagnostic"].map(arm=>[arm,{instructions:median(runs.filter(r=>r.arm===arm).map(r=>r.instructions)),cpu_s:median(runs.filter(r=>r.arm===arm).map(r=>r.cpu_s))}]));
 rows.push({...entry,normal_command:normal,diagnostic_command:diagnostic,runs,medians,ordinary_instruction_ratio:medians.after.instructions/medians.before.instructions,
  diagnostic_command_instruction_ratio:medians.diagnostic.instructions/medians.after.instructions,
  analysis:{header,completed,work:Number(/work=(\d+)\//.exec(header)![1]),points,events},executing_thread_bytes:bytes,executing_thread_cpu:cpu,
  diagnostic_thread_cpu_share:cpu.phases[0].cpu_ns/(1e9*cpu.process_cpu.total_s),instrument_thread_cpu_ratio:bytes.phases[0].instrumented_thread_cpu_ns/cpu.phases[0].cpu_ns,instrument_command_cpu_ratio:bytes.process_cpu.total_s/cpu.process_cpu.total_s});
 const source=readFileSync(import.meta.filename,"utf8");
 writeFileSync(out+"/summary.json",JSON.stringify({measured_commit:tip,baseline_commit:beforeCommit,composed_parent:composedParent,parent_build_inputs_identical:true,generating_command:[process.execPath,import.meta.filename,...process.argv.slice(2)],suite,artifacts,observer,work_profile:COMPILE_WORK_PROFILE,work_settings:compileWorkSettings(environment),
  scope:"Ordinary preparation and explicit regions diagnostic command measured separately; diagnostic rendering is included in command deltas, not mislabelled solver work. CPU body probe has no allocator interposer. Byte probe uses an explicitly instrumented allocator-only CLI and reports selected-thread Rust requested payload, with epoch header/padding excluded separately; ordinary instructions and the CPU bracket use the untouched formal CLI.",
  instrument:{sha256:sha(source),source},rows},null,2)+"\n");
